<?php if(!defined('ABSPATH'))exit;$d=woogit_portal_data();get_header();if(!$d['authenticated']){woogit_render_status('error','نشست شما منقضی شده است.');get_footer();return;}$u=$d['user'];$webPasswordConfigured=!empty($u['web_password_configured']);?><section class="wg-section wg-portal"><div class="wg-container"><div class="wg-section__head"><div><span class="wg-eyebrow">Account / Security</span><h1>حساب و امنیت</h1><p><?php echo $webPasswordConfigured?'اطلاعات حساب و Web Session را مدیریت کنید.':'اتصال فروشگاه با موفقیت انجام شد. برای ورودهای بعدی ابتدا رمز عبور وب خود را تنظیم کنید.'; ?></p></div></div><div class="wg-grid wg-grid--2"><article class="wg-card"><h2>حساب</h2><p>ایمیل فعلی: <strong dir="ltr"><?php echo woogit_safe_text(woogit_portal_value($u,['email','contact_email'],'—')); ?></strong></p><form class="wg-form" data-woogit-portal-action="contact_email"><label>ایمیل تماس<input type="email" name="email" required autocomplete="email" value="<?php echo esc_attr(woogit_portal_value($u,['email','contact_email'],'')); ?>"></label><button class="wg-btn" type="submit">ذخیره ایمیل</button><p class="wg-form-message" aria-live="polite"></p></form></article><?php if(!$webPasswordConfigured): ?><article class="wg-card"><h2>تنظیم رمز عبور وب</h2><p>این رمز برای ورودهای بعدی به حساب WooGit استفاده می‌شود و باید بین ۱۲ تا ۲۵۶ کاراکتر باشد.</p><form class="wg-form" data-woogit-portal-action="setup_web_credentials"><label>رمز عبور وب<input type="password" name="password" required minlength="12" maxlength="256" autocomplete="new-password"></label><label>تکرار رمز عبور وب<input type="password" name="password_confirmation" required minlength="12" maxlength="256" autocomplete="new-password"></label><button class="wg-btn" type="submit">تنظیم رمز عبور وب</button><p class="wg-form-message" aria-live="polite"></p></form></article><?php else: ?><article class="wg-card"><h2>تغییر رمز</h2><form class="wg-form" data-woogit-portal-action="password"><label>رمز فعلی<input type="password" name="current_password" required autocomplete="current-password"></label><label>رمز جدید<input type="password" name="password" required minlength="12" maxlength="256" autocomplete="new-password"></label><label>تکرار رمز جدید<input type="password" name="password_confirmation" required minlength="12" maxlength="256" autocomplete="new-password"></label><button class="wg-btn" type="submit">تغییر رمز و خروج امن</button><p class="wg-form-message" aria-live="polite"></p></form></article><?php endif; ?></div><div class="wg-card"><h2>نشست وب</h2><p>نشست منقضی‌شده locally احیا نمی‌شود. پس از تغییر رمز یا پایان اعتبار، ورود مجدد لازم است.</p><button class="wg-btn wg-btn--ghost" type="button" data-woogit-logout>خروج از حساب</button></div></div></section><?php get_footer(); ?>